//! Writing the config file. nioxd only ever writes it to add a generated
//! identity on first run.

use std::fs::{self, DirBuilder, File, OpenOptions, Permissions};
use std::io::{self, Write as _};
use std::os::unix::fs::{DirBuilderExt as _, OpenOptionsExt as _, PermissionsExt as _};
use std::path::Path;

use crate::{LoadError, PrivateKey};

fn identity_table(key: &PrivateKey) -> String {
    format!(
        "# This machine's identity, generated by nioxd on first run. Keep it\n\
         # secret: anyone with this key can impersonate this machine. Peers\n\
         # trust it by its public key (`nioxctl pubkey`).\n\
         [identity]\n\
         private_key = \"{}\"\n",
        key.to_base64()
    )
}

/// The config written on first run when no file exists.
pub(crate) fn default_config(key: &PrivateKey) -> String {
    format!(
        r#"# niox configuration, read by nioxd. Apply changes with
# `systemctl reload nioxd`.

{identity}
[transport]
# UDP port nioxd listens on. Peer addresses without a port use it too.
port = 4777

[km]
# Focus-switch hotkey as evdev key codes (see `evtest` or
# linux/input-event-codes.h): press the second key while holding the
# first. A single code makes a one-key hotkey. Default: Left Meta (125)
# + Grave (41), as in NKMS.
hotkey = [125, 41]

# One [[peer]] table per machine this one talks to. `role` is the peer's
# role relative to this machine: "client" if this machine drives its
# keyboard and mouse, "host" if it drives this machine's.
#
# [[peer]]
# name = "desk"
# address = "192.168.1.20"   # or "desk.lan", "192.168.1.20:4777"
# public_key = "<`nioxctl pubkey` on that machine>"
# role = "client"
"#,
        identity = identity_table(key),
    )
}

/// Appends an `[identity]` table to an existing config that has none.
/// Appending a new table is always valid TOML when the document has no
/// `identity` key, which the caller has checked.
pub(crate) fn append_identity(text: &str, key: &PrivateKey) -> String {
    let mut out = text.to_owned();
    if !out.is_empty() && !out.ends_with('\n') {
        out.push('\n');
    }
    if !out.is_empty() {
        out.push('\n');
    }
    out.push_str(&identity_table(key));
    out
}

/// Atomically replaces `path` with `text`, mode `0600`, creating the
/// parent directory if needed.
pub(crate) fn write_private(path: &Path, text: &str) -> Result<(), LoadError> {
    let io_err = |action, path: &Path| {
        let path = path.to_owned();
        move |source| LoadError::Io {
            action,
            path,
            source,
        }
    };

    let dir = match path.parent() {
        Some(dir) if !dir.as_os_str().is_empty() => dir,
        _ => Path::new("."),
    };
    if !dir.exists() {
        DirBuilder::new()
            .recursive(true)
            .mode(0o755)
            .create(dir)
            .map_err(io_err("create directory", dir))?;
    }

    let file_name = path
        .file_name()
        .ok_or_else(|| LoadError::Io {
            action: "write",
            path: path.to_owned(),
            source: io::Error::new(io::ErrorKind::InvalidInput, "not a file path"),
        })?
        .to_string_lossy();
    let tmp = dir.join(format!(".{file_name}.tmp"));

    // A stale temp file from a crash may have other permissions; never
    // reuse it.
    match fs::remove_file(&tmp) {
        Ok(()) => {}
        Err(e) if e.kind() == io::ErrorKind::NotFound => {}
        Err(e) => return Err(io_err("remove", &tmp)(e)),
    }
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(&tmp)
        .map_err(io_err("create", &tmp))?;
    // `mode` is filtered by the umask; make sure it's exactly 0600.
    file.set_permissions(Permissions::from_mode(0o600))
        .map_err(io_err("chmod", &tmp))?;
    file.write_all(text.as_bytes())
        .and_then(|()| file.sync_all())
        .map_err(io_err("write", &tmp))?;
    drop(file);

    fs::rename(&tmp, path).map_err(io_err("rename to", path))?;
    File::open(dir)
        .and_then(|d| d.sync_all())
        .map_err(io_err("sync", dir))?;
    Ok(())
}
